      { qty: 10, unitPrice: 9500, vatRate: 21 },
      { qty: 3, unitPrice: 6000, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 5 * 8500 + 10 * 9500 + 3 * 6000;
  const expectedVAT = 8925 + 19950 + 1620;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
