test('invoiceTotals total formula: subtotal - discount + vat', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €425, discount 2.5% = €10.625 ≈ €10.62 (banker's rounding), net €414.38, VAT €87.02
      { sku: 'LOGO-PACK', qty: 2, discountPercent: 10 }, // €2400, discount 10% = €240, net €2160, VAT €453.60
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 240000;
  const expectedDiscount = 1062 + 24000; // line 1: 42500*2.5/100 = 1062.5 → 1062 (round half to even)
  const expectedVAT = 8702 + 45360; // rounded per line
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVAT;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedTotal);
});

