    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
  assert.equal(result.value.lines[0].discountPercent, undefined); // standard tier
});

