test('createInvoice EOM works for different months', () => {
  // February in non-leap year
  let result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
