  // December (year boundary)
  result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-20',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2025-12-31');
});

